import { chromium } from 'playwright';
import assert from 'node:assert/strict';

const BASE = 'http://localhost:4173/';
const SHOTS = '/tmp/pw-check/shots';
const { mkdirSync } = await import('node:fs');
mkdirSync(SHOTS, { recursive: true });

const browser = await chromium.launch();
const context = await browser.newContext({ colorScheme: 'light', viewport: { width: 1000, height: 800 } });
const page = await context.newPage();

const errors = [];
page.on('console', (msg) => { if (msg.type() === 'error') errors.push(msg.text()); });
page.on('pageerror', (err) => errors.push(`pageerror: ${err.message}`));

const bodyClass = () => page.evaluate(() => document.body.className);
const bg = () => page.evaluate(() => getComputedStyle(document.querySelector('.app')).backgroundColor);
const h1 = () => page.locator('main h1').innerText();
const navActive = () => page.locator('.app__nav [aria-current="page"]').innerText();

// 1. Initial load: home page, light theme (system pref = light)
await page.goto(BASE);
await page.waitForSelector('main h1');
assert.equal(await h1(), 'Добро пожаловать');
assert.equal(await navActive(), 'Главная');
assert.match(await bodyClass(), /g-root_theme_light/);
const lightBg = await bg();
await page.screenshot({ path: `${SHOTS}/1-home-light.png` });
console.log('ok: home page, light theme, bg =', lightBg);

// 2. Navigate via nav buttons
await page.getByRole('link', { name: 'Задачи', exact: true }).click();
await page.waitForFunction(() => location.hash === '#/tasks');
assert.equal(await h1(), 'Задачи');
assert.equal(await navActive(), 'Задачи');
console.log('ok: nav to tasks');

// 3. Add tasks, toggle, delete
const input = page.getByPlaceholder('Что нужно сделать?');
const addBtn = page.getByRole('button', { name: 'Добавить' });
assert.equal(await addBtn.isDisabled(), true, 'add disabled when empty');
await input.fill('Купить молоко');
await input.press('Enter');
await input.fill('Написать отчёт');
await addBtn.click();
assert.equal(await page.locator('.task-item').count(), 2);
assert.equal(await input.inputValue(), '');
await page.locator('.task-item').first().locator('input[type=checkbox]').check();
assert.match(await page.locator('.task-item').first().getAttribute('class'), /task-item--done/);
assert.match(await page.locator('.task-footer').innerText(), /Выполнено: 1 из 2/);
console.log('ok: add + toggle');

// 4. Persistence across reload
await page.reload();
await page.waitForSelector('.task-item');
assert.equal(await page.locator('.task-item').count(), 2);
assert.match(await page.locator('.task-item').first().getAttribute('class'), /task-item--done/);
console.log('ok: tasks persist across reload');
await page.screenshot({ path: `${SHOTS}/2-tasks-light.png` });

// 5. Delete one task
await page.getByRole('button', { name: 'Удалить задачу: Написать отчёт' }).click();
assert.equal(await page.locator('.task-item').count(), 1);
console.log('ok: delete');

// 6. About page + browser back/forward
await page.getByRole('link', { name: 'О приложении', exact: true }).click();
await page.waitForFunction(() => location.hash === '#/about');
assert.equal(await h1(), 'О приложении');
await page.goBack();
await page.waitForFunction(() => location.hash === '#/tasks');
assert.equal(await h1(), 'Задачи');
console.log('ok: about + back button');

// 7. Unknown hash falls back to home
await page.goto(BASE + '#/nope');
await page.waitForSelector('main h1');
assert.equal(await h1(), 'Добро пожаловать');
console.log('ok: unknown route -> home');

// 8. Theme toggle
await page.goto(BASE + '#/tasks');
await page.waitForSelector('main h1');
const toggle = page.locator('label', { hasText: 'Тёмная тема' });
await toggle.click();
await page.waitForFunction(() => document.body.className.includes('g-root_theme_dark'));
assert.match(await bodyClass(), /g-root_theme_dark/);
assert.notEqual(await bg(), lightBg);
assert.equal(await page.evaluate(() => localStorage.getItem('app-theme')), 'dark');
await page.screenshot({ path: `${SHOTS}/3-tasks-dark.png` });
console.log('ok: toggle to dark, bg =', await bg());

// 9. Theme persists across reload and across page navigation
await page.reload();
await page.waitForSelector('main h1');
assert.match(await bodyClass(), /g-root_theme_dark/);
await page.getByRole('link', { name: 'О приложении', exact: true }).click();
await page.waitForFunction(() => location.hash === '#/about');
assert.match(await bodyClass(), /g-root_theme_dark/);
assert.equal(await page.getByRole('switch').isChecked(), true);
await page.screenshot({ path: `${SHOTS}/4-about-dark.png` });
console.log('ok: dark persists across reload + navigation');

// 10. Toggle back to light
await toggle.click();
await page.waitForFunction(() => document.body.className.includes('g-root_theme_light'));
assert.equal(await page.evaluate(() => localStorage.getItem('app-theme')), 'light');
assert.equal(await bg(), lightBg);
console.log('ok: toggle back to light');

// 11. Saved choice overrides system preference
const dark = await browser.newContext({ colorScheme: 'dark' });
const p2 = await dark.newPage();
await p2.goto(BASE);
await p2.waitForSelector('main h1');
assert.match(await p2.evaluate(() => document.body.className), /g-root_theme_dark/, 'system dark -> dark');
await p2.evaluate(() => localStorage.setItem('app-theme', 'light'));
await p2.reload();
await p2.waitForSelector('main h1');
assert.match(await p2.evaluate(() => document.body.className), /g-root_theme_light/, 'saved light beats system dark');
await dark.close();
console.log('ok: system preference + saved override');

assert.deepEqual(errors, [], 'no console/page errors');
console.log('ok: no console errors');
await browser.close();
console.log('ALL CHECKS PASSED');

