await page.getByRole('button', { name: 'Удалить задачу: Написать отчёт' }).click();
assert.equal(await page.locator('.task-item').count(), 1);
console.log('ok: delete');

// 6. About page + browser back/forward
await page.getByRole('link', { name: 'О приложении', exact: true }).click();
await page.waitForFunction(() => location.hash === '#/about');
assert.equal(await h1(), 'О приложении');
await page.goBack();
await page.waitForFunction(() => location.hash === '#/tasks');
assert.equal(await h1(), 'Задачи');
console.log('ok: about + back button');

// 7. Unknown hash falls back to home
await page.goto(BASE + '#/nope');
await page.waitForSelector('main h1');
assert.equal(await h1(), 'Добро пожаловать');
console.log('ok: unknown route -> home');

// 8. Theme toggle
await page.goto(BASE + '#/tasks');
await page.waitForSelector('main h1');
const toggle = page.locator('label', { hasText: 'Тёмная тема' });
await toggle.click();
await page.waitForFunction(() => document.body.className.includes('g-root_theme_dark'));
assert.match(await bodyClass(), /g-root_theme_dark/);
assert.notEqual(await bg(), lightBg);
assert.equal(await page.evaluate(() => localStorage.getItem('app-theme')), 'dark');
await page.screenshot({ path: `${SHOTS}/3-tasks-dark.png` });
console.log('ok: toggle to dark, bg =', await bg());

// 9. Theme persists across reload and across page navigation
await page.reload();
await page.waitForSelector('main h1');
assert.match(await bodyClass(), /g-root_theme_dark/);
await page.getByRole('link', { name: 'О приложении', exact: true }).click();
await page.waitForFunction(() => location.hash === '#/about');
assert.match(await bodyClass(), /g-root_theme_dark/);
assert.equal(await page.getByRole('switch').isChecked(), true);
await page.screenshot({ path: `${SHOTS}/4-about-dark.png` });
console.log('ok: dark persists across reload + navigation');

// 10. Toggle back to light
await toggle.click();
await page.waitForFunction(() => document.body.className.includes('g-root_theme_light'));
assert.equal(await page.evaluate(() => localStorage.getItem('app-theme')), 'light');
assert.equal(await bg(), lightBg);
console.log('ok: toggle back to light');

// 11. Saved choice overrides system preference
const dark = await browser.newContext({ colorScheme: 'dark' });
const p2 = await dark.newPage();
await p2.goto(BASE);
await p2.waitForSelector('main h1');
assert.match(await p2.evaluate(() => document.body.className), /g-root_theme_dark/, 'system dark -> dark');
await p2.evaluate(() => localStorage.setItem('app-theme', 'light'));
await p2.reload();
await p2.waitForSelector('main h1');
assert.match(await p2.evaluate(() => document.body.className), /g-root_theme_light/, 'saved light beats system dark');
await dark.close();
console.log('ok: system preference + saved override');

assert.deepEqual(errors, [], 'no console/page errors');
console.log('ok: no console errors');
await browser.close();
console.log('ALL CHECKS PASSED');

